use median_finder::MedianFinder;

#[test]
fn test_single_number() {
    let mut mf = MedianFinder::new();
    mf.add_num(3);
    assert!((mf.find_median() - 3.0).abs() < 1e-9);
}

#[test]
fn test_two_numbers() {
    let mut mf = MedianFinder::new();
    mf.add_num(1);
    mf.add_num(2);
    assert!((mf.find_median() - 1.5).abs() < 1e-9);
}

#[test]
fn test_odd_count() {
    let mut mf = MedianFinder::new();
    for n in [1, 2, 3] { mf.add_num(n); }
    assert!((mf.find_median() - 2.0).abs() < 1e-9);
}

#[test]
fn test_unsorted_input() {
    let mut mf = MedianFinder::new();
    for n in [5, 3, 8, 1, 7] { mf.add_num(n); }
    // sorted: [1,3,5,7,8] → median = 5
    assert!((mf.find_median() - 5.0).abs() < 1e-9);
}

#[test]
fn test_even_count_average() {
    let mut mf = MedianFinder::new();
    for n in [2, 4, 6, 8] { mf.add_num(n); }
    // sorted: [2,4,6,8] → median = (4+6)/2 = 5.0
    assert!((mf.find_median() - 5.0).abs() < 1e-9);
}

